-- Certification extended to Thursday, Nov 5 (Sean, 2026-10-29) in the published playbooks, the Oct 29 Hot Lab notes and the
-- tracker. Applied through ve-once-bcps-cert-extend (now a 410 stub).
update public.briefings set updated_at=now(), content =
 replace(regexp_replace(regexp_replace(content, '<p><strong>Status\.</strong>.*?</p>', '<p><strong>Status.</strong> Certification is due <strong>Thursday, November 5, 2026</strong>, extended from October 30 to give everyone a little more room. As of October 29, 47 department WCMs have completed it. If anything is in the way, send a message from BCPS MarComm or bring it to Hot Lab on Tuesday, November 3 or Thursday, November 5; we will work it out with you. After the deadline, the District Web Team follows up with anyone who has not finished. The department audit is live on your dashboard under <strong>Run Audit</strong>; first, check that it lists only pages your team manages (see Your Department Audit below).</p>'),
   'Certification deadline: October 30, 2026\.</strong>.*?before update access is granted\.', 'Certification deadline: Thursday, November 5, 2026.</strong> Extended from October 30. All Web Content Managers complete the course by this date; if you need more time or help, tell us and we will work it out with you. New WCMs complete it before update access is granted.'),
   '<h2>October 29, 2026</h2>', '<h2>October 29, 2026</h2><p>Certification extended to Thursday, November 5. The Monday, November 2 access check is replaced by a District Web Team follow-up with anyone who has not finished.</p>')
where slug='wcm-department' and brand_slug='bcps' and content not like '%extended from October 30%';
update public.briefings set updated_at=now(), content =
 replace(replace(replace(regexp_replace(content, '<p><strong>Status\.</strong>.*?</p>', '<p><strong>Status.</strong> Certification is due <strong>Thursday, November 5, 2026</strong>, extended from October 30 to give WCMs a little more room. 47 department WCMs have completed it. WCMs still finishing are getting a note from Sean with the new date and an offer of help. If someone new has taken over your department''s pages, as happened in Emergency Management this week, tell us and we will fast-track them. A quick check-in with your WCM on where they are in the course helps most this week. After the deadline, the District Web Team follows up with each WCM who has not finished.</p>'),
   '<strong>October 30, 2026</strong>. Anyone new to the role finishes sooner', '<strong>Thursday, November 5, 2026</strong> (extended from October 30). Anyone new to the role finishes sooner'), '<p>As of October 28, 41 department WCMs have completed certification. Starting Monday, November 2, any WCM who has not finished loses access to edit your department pages, and it is restored as soon as they complete the course. The next Hot Lab is Tuesday, November 3.</p>', '<p>As of October 29, 47 department WCMs have completed certification. Hot Labs on Tuesday, November 3 and Thursday, November 5 are the place for WCMs to get help finishing. After the deadline, the District Web Team follows up with each WCM who has not finished.</p>'),
   '<p><span class="change-date">October 29, 2026.</span> Status updated', '<p><span class="change-date">October 29, 2026.</span> Certification extended to Thursday, November 5. The Monday, November 2 access check is replaced by a District Web Team follow-up with each WCM who has not finished.</p>
' || '<p><span class="change-date">October 29, 2026.</span> Status updated')
where slug='director-department' and brand_slug='bcps' and content not like '%extended from October 30%';
update public.briefings set updated_at=now(), content = replace(content, 'Certification deadline: October 30, 2026.</strong> That', 'Certification deadline: Thursday, November 5, 2026</strong> (extended from October 30). That')
where slug='bcps-wcm-registration-2026-27' and brand_slug='bcps' and content like '%Certification deadline: October 30, 2026.</strong> That%';
update public.briefings set updated_at=now(), content = replace(replace(content,
   '<div class="section-block lead-summary">', '<div class="section-block lead-summary"><div class="update-row"><div class="hl-label">Update, October 29</div><div class="hl-text">After this session, the certification was extended to <strong>Thursday, November 5</strong>. The Monday, November 2 check below no longer applies; the District Web Team follows up with anyone who has not finished.</div></div>'),
   '<div class="body"><h2>October 29, 2026</h2>', '<div class="body"><h2>October 29, 2026 (update)</h2><p>Certification extended to Thursday, November 5; update note added at the top.</p><h2>October 29, 2026</h2>')
where slug='bcps-hot-lab-dept-wcms-2026-10-29' and content not like '%Update, October 29%';
update public.bcps_assignment_tags set updated_at=now(), description_override = 'Department WCM certification, extended from Oct 30 to Thursday, Nov 5 (Sean, Oct 29). Follow-up emails go out from the Certification Follow-up page (progress, opens and clicks live). Nudge on Tue, Nov 3 to anyone who has not moved; Hot Labs Nov 3 and Nov 5; review Monday, Nov 9, case by case, with no blanket access shutoff. LAB course completion for certified WCMs (raised by Patricia Sapp) and the public /lab link for new WCMs. Merged here: LAB Course Completion.'
where assignment_slug='canvas-course-departments';
insert into public.bcps_assignment_notes (assignment_slug, note_text, author)
select 'canvas-course-departments', 'Oct 29: deadline extended to Thursday, Nov 5. Plan: WCM follow-up and director email today; reminder Mon Nov 2; nudge Tue Nov 3; deadline Thu Nov 5; review Mon Nov 9.', 'Sean A. Russell'
where not exists (select 1 from public.bcps_assignment_notes where assignment_slug='canvas-course-departments' and note_text like 'Oct 29: deadline extended%');
insert into public.stream_events (timestamp, owner, station, summary, status, task_id) values (now(),'logan','bcps','Certification extended to Thursday, Nov 5 (Sean): app code (PR 205), WCM and Director Playbooks, Registration Playbook, Oct 29 Hot Lab notes update line and the tracker row updated; follow-up emails rewritten around the new date.','completed','canvas-course-departments');
